/**
 * Points boxers to the freely licensed photos in public/images/commons and stores the photo credit.
 * Source data: src/data/imageCredits.json (generated by back/tools/registry-scripts/download.mjs).
 *
 * Run the SQL migration in back/migrations first, then:
 *   npx ts-node src/scripts/applyImageCredits.ts --dry-run   # only show matches
 *   npx ts-node src/scripts/applyImageCredits.ts             # write to DB
 */
import fs from 'fs'
import path from 'path'
import { Op } from 'sequelize'
import sequelize from '../config/sequelizeConfig'
import BoxerModel from '../models/boxerModel'

interface CreditEntry {
    key: string
    name: string
    nameAscii?: string
    avatarImg: string
    img: string
    imageAuthor: string | null
    imageLicense: string
    imageLicenseUrl: string | null
    imageSourceUrl: string
    skip?: string
    review?: string
}

const dryRun = process.argv.includes('--dry-run')
const credits: CreditEntry[] = JSON.parse(
    fs.readFileSync(path.join(__dirname, '..', 'data', 'imageCredits.json'), 'utf8')
)
const cut = (s: string | null) => (s && s.length > 255 ? s.slice(0, 254) + '…' : s)

// Exact full name first, then name without accents, then a surname match only when it is unambiguous.
const findBoxer = async (entry: CreditEntry) => {
    for (const name of [entry.name, entry.nameAscii].filter(Boolean) as string[]) {
        const found = await BoxerModel.findAll({ where: { name: { [Op.iLike]: name } } })
        if (found.length === 1) return { boxer: found[0], how: 'full name' }
    }
    const surname = (entry.nameAscii ?? entry.name).split(' ').pop()!
    const found = await BoxerModel.findAll({ where: { name: { [Op.iLike]: `%${surname}%` } } })
    if (found.length === 1) return { boxer: found[0], how: `surname "${surname}"` }
    return { boxer: null, how: found.length ? `ambiguous: ${found.map((b) => b.get('name')).join(', ')}` : 'not found' }
}

const main = async () => {
    const problems: string[] = []
    for (const entry of credits) {
        if (entry.skip) {
            problems.push(`${entry.name}: skipped (${entry.skip})`)
            continue
        }
        const { boxer, how } = await findBoxer(entry)
        if (!boxer) {
            problems.push(`${entry.name}: ${how}`)
            continue
        }
        console.log(`${dryRun ? '[dry-run] ' : ''}${entry.name} -> ${boxer.get('name')} (${how})`)
        if (entry.review) problems.push(`${entry.name}: check the photo (${entry.review})`)
        if (dryRun) continue
        await boxer.update({
            avatarImg: entry.avatarImg,
            img: entry.img,
            imageAuthor: cut(entry.imageAuthor),
            imageLicense: entry.imageLicense,
            imageLicenseUrl: entry.imageLicenseUrl,
            imageSourceUrl: entry.imageSourceUrl,
        })
    }
    if (problems.length) console.log('\nNeeds attention:\n- ' + problems.join('\n- '))
    await sequelize.close()
}

main().catch(async (e) => {
    console.error(e)
    await sequelize.close()
    process.exit(1)
})
